// 5V 轨回读（GPIO26, ADC2_CH8, ATTEN_DB11）
// V4.2.7 修正：GPIO26 = ADC2_CH8（非 CH9），增加显式 ADC2 重新初始化
float read_5v_rail_voltage(void) {
    int raw = 0;
    adc2_config_channel_atten(ADC2_CHANNEL_8, ADC_ATTEN_DB_11);  // V4.2.7 修正：CH8 对应 GPIO26
    adc2_get_raw(ADC2_CHANNEL_8, ADC_WIDTH_BIT_12, &raw);
    return (float)raw * 3.3f / 4095.0f * 2.0f;  // 分压比1:1
}

// VBUS 检测（GPIO36, ADC1_CH0）
bool mains_power_detected(void) {
    int raw = 0;
    adc1_config_channel_atten(ADC1_CHANNEL_0, ADC_ATTEN_DB_11);
    raw = adc1_get_raw(ADC1_CHANNEL_0);
    float v = (float)raw * 3.3f / 4095.0f * 2.0f;
    return v > 2.0f;  // VBUS > 4.0V
}

// BH1750 传感器使能（含复位时序）
