void enable_bh1750(void) {
    gpio_set_level(GPIO_SENSOR_PWR, 1);  // GPIO13 导通传感器 VCC
    // BH1750 数据手册要求：VCC 上升沿后 DVI 高电平 ≥1μs，之后至少 2ms 才能发 I²C 命令
    // 本方案 DVI 直接接 VCC，2ms 延时同时满足两个条件
    vTaskDelay(pdMS_TO_TICKS(2));
}

