// V4.2.7: 5V 关断校验（含延时 + WDT 管理）
void verify_5v_shutdown(void) {
    // V4.2.7: 先禁用看门狗，避免 15s 等待期间 WDT 复位
    gpio_set_level(GPIO_WDT_EN, 1);  // 拉高 TPS3820 /EN 禁用看门狗

    // 关断 MP2307
    gpio_set_level(GPIO_EN_5V, 0);

    // V4.2.7: 等待 ≥15s，让 100kΩ 泄放电阻充分放电（44μF×100kΩ=4.4s，15s≈3.4τ）
    vTaskDelay(pdMS_TO_TICKS(15000));

    // 读取 3 次，确认 <0.5V
    for (int i = 0; i < 3; i++) {
        float v = read_5v_rail_voltage();
        if (v < 0.5f) {
            return;  // 校验通过
        }

